def add_finishing(add):
    add('dinamica', 'Text3: eliminări minime și lanț', 'date.in conține până la 500 de cuvinte lowercase pe mai multe linii. Păstrează un subșir în care ultima literă a unui cuvânt este prima a următorului. Scrie în date.out numărul total de cuvinte, numărul minim de eliminări, apoi cuvintele păstrate, fiecare pe o linie. Orice lanț optim este acceptat. Variantă de studiu cu limite reduse a problemei Text3.', 'Păstrează cel mai bun final pentru fiecare literă și predecesorii. Compară cu soluția O(n²) care încearcă toate cuvintele anterioare.', 'with open("date.in") as f:\n    a = f.read().split()\nbest = {}\ndp = [0] * len(a)\npred = [-1] * len(a)\nfor i, w in enumerate(a):\n    length, j = best.get(w[0], (0, -1))\n    dp[i], pred[i] = length + 1, j\n    if dp[i] > best.get(w[-1], (0, -1))[0]:\n        best[w[-1]] = (dp[i], i)\ni = max(range(len(a)), key=lambda i: dp[i]) if a else -1\npath = []\nwhile i != -1:\n    path.append(a[i])\n    i = pred[i]\nwith open("date.out", "w") as f:\n    print(len(a), file=f)\n    print(len(a) - len(path), file=f)\n    for word in reversed(path):\n        print(word, file=f)', [('ab bc\ncd','3\n0\nab\nbc\ncd'),('aa bb','2\n1\naa'),('','0\n0')], 'Aprofundare', validator='text3', inputFile='date.in', outputFile='date.out', externalSource='https://www.infoarena.ro/problema/text3')
    add('dinamica', 'Subset sum: reconstruiește', 'Citește o listă de numere naturale și S ≥ 0. Dacă nu există submulțime de sumă S, afișează -1. Altfel afișează S pe prima linie și indicii de la 1 ai unei submulțimi valide pe a doua. Fiecare poziție poate fi folosită cel mult o dată.', 'Memorează pentru fiecare sumă nouă suma anterioară și indicele obiectului. Parcurge descrescător.', 'a = list(map(int, input().split()))\nS = int(input())\ndp = [True] + [False] * S\npred = {}\nfor i, x in enumerate(a, 1):\n    for s in range(S, x - 1, -1):\n        if not dp[s] and dp[s - x]:\n            dp[s] = True\n            pred[s] = (s - x, i)\nif not dp[S]:\n    print(-1)\nelse:\n    print(S)\n    path = []\n    while S:\n        S, i = pred[S]\n        path.append(i)\n    print(*reversed(path))', [('12 1 3 4 5 7\n14','14\n3 4 6'),('2 4\n3','-1'),('0 1\n0','0\n')], 'Aplicare', validator='subset')
    add('dinamica', 'Vectorii: reconstruiește alegerea', 'Citește n k și n linii de naturale pozitive. Alege exact un element din fiecare linie cu suma k. Fără soluție afișează 0; altfel 1, apoi valorile alese pe a doua linie. Orice alegere validă este acceptată.', 'Păstrează pentru fiecare nivel și sumă perechea (suma_anterioară,valoare_aleasă).', 'n, k = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(n)]\nreachable = {0}\npred = []\nfor row in a:\n    p = {}\n    for s in reachable:\n        for x in row:\n            if s + x <= k:\n                p.setdefault(s + x, (s, x))\n    pred.append(p)\n    reachable = set(p)\nif k not in reachable:\n    print(0)\nelse:\n    print(1)\n    path = []\n    for p in reversed(pred):\n        k, x = p[k]\n        path.append(x)\n    print(*reversed(path))', [('3 11\n3 5 10 8\n4 3 7\n6 8 2 9','1\n5 4 2'),('2 5\n2\n2','0'),('0 0','1\n')], 'Aprofundare', validator='vectors')
    add('dinamica', 'Lanț pe două litere în O(n)', 'Citește cuvinte lowercase cu minimum două litere. Afișează lungimea maximă a unui subșir cu suprapunere pe două litere și un astfel de lanț. Folosește un dicționar indexat prin ultimele două litere pentru O(n) operații pe cuvinte.', 'Pentru cuvântul curent, caută cel mai bun lanț al cărui sufix coincide cu prefixul curent; actualizează cheia sufixului.', 'a = input().split()\nbest = {}\ndp = [0] * len(a)\npred = [-1] * len(a)\nfor i, w in enumerate(a):\n    length, j = best.get(w[:2], (0, -1))\n    dp[i], pred[i] = length + 1, j\n    if dp[i] > best.get(w[-2:], (0, -1))[0]:\n        best[w[-2:]] = (dp[i], i)\ni = max(range(len(a)), key=lambda i: dp[i]) if a else -1\npath = []\nwhile i != -1:\n    path.append(a[i])\n    i = pred[i]\nprint(len(path))\nprint(*reversed(path))', [('masa carte sac teatru tema rustic sare','3\ncarte teatru rustic'),('abcd cdef efgh','3\nabcd cdef efgh'),('\n','0\n')], 'Aprofundare', validator='wordchain')
    add('greedy', 'Joburi rapide cu sloturi', 'Citește n și n perechi profit termen, profit ≥ 0 și termen în 1..n. Afișează profitul maxim și o programare fără pauze a indicilor. Folosește sortare după profit și o structură de mulțimi disjuncte pentru ultimul slot liber, în locul căutării liniare.', 'parent[t] conduce la cel mai apropiat slot liber ≤ t; compresia drumului accelerează căutările repetate.', 'n = int(input())\na = [(*map(int, input().split()), i + 1) for i in range(n)]\na.sort(reverse=True)\nparent = list(range(n + 1))\nslots = {}\ndef find(x):\n    r = x\n    while parent[r] != r:\n        r = parent[r]\n    while parent[x] != x:\n        old = parent[x]\n        parent[x] = r\n        x = old\n    return r\nfor p, d, i in a:\n    t = find(d)\n    if t:\n        slots[t] = (p, i)\n        parent[t] = find(t - 1)\nprint(sum(p for p, i in slots.values()))\nprint(*(slots[t][1] for t in sorted(slots)))', [('4\n4 3\n1 1\n2 1\n5 3','11\n3 1 4'),('1\n7 1','7\n1'),('0','0\n')], 'Aprofundare', validator='jobs')
    add('greedy', 'Strategia de paritate în joc', 'Prima linie conține un număr par de valori pozitive. A doua conține exact n/2 mutări S sau D ale adversarului, fără spații. Primul jucător urmărește paritatea pozițiilor inițiale cu suma mai mare (la egalitate, pozițiile 0,2,...). Simulează jocul și afișează sumele celor doi, apoi mutările primului jucător. Indicii inițiali sunt de la 0.', 'După fiecare mutare a adversarului, primul poate alege din nou un capăt cu paritatea dorită.', 'a = list(map(int, input().split()))\nopp = input()\nparity = 0 if sum(a[::2]) >= sum(a[1::2]) else 1\nl, r = 0, len(a) - 1\ns1 = s2 = 0\nmoves = []\nfor move in opp:\n    if l % 2 == parity:\n        s1 += a[l]\n        l += 1\n        moves.append("S")\n    else:\n        s1 += a[r]\n        r -= 1\n        moves.append("D")\n    if move == "S":\n        s2 += a[l]\n        l += 1\n    else:\n        s2 += a[r]\n        r -= 1\nprint(s1, s2)\nprint("".join(moves))', [('2 1 4 3\nSS','6 4\nSS'),('2 1 4 3\nDS','6 4\nSD'),('5 1\nD','5 1\nS')], 'Aprofundare')
    add('module', 'Coduri aleatorii cu format verificat', 'Citește n, apoi n nume fără spații. Definește genereaza_cod(), care construiește aleator o majusculă, trei minuscule și patru cifre ASCII. Afișează nume cod pe fiecare linie. Testele acceptă orice cod cu formatul cerut; acestea sunt date de exercițiu.', 'Folosește random.choice/choices și constantele din string. Nu compara ieșirea cu un singur șir aleator de referință.', 'import random\nimport string\ndef genereaza_cod():\n    return random.choice(string.ascii_uppercase) + "".join(random.choices(string.ascii_lowercase, k=3)) + "".join(random.choices(string.digits, k=4))\nn = int(input())\nfor _ in range(n):\n    print(input(), genereaza_cod())', [('2\nAna\nDan','Ana COD_VALID\nDan COD_VALID'),('1\nEva','Eva COD_VALID'),('0','')], 'Aplicare', validator='codes', requiredFunction='genereaza_cod')
    add('backtracking', 'Aranjamente', 'Citește n k, 1 ≤ k ≤ n ≤ 6. Afișează lexicografic toate aranjamentele de k valori distincte din 1..n, câte unul pe linie. Ordinea valorilor contează.', 'Alege orice valoare încă nefolosită, fără a impune ordine crescătoare.', 'n, k = map(int, input().split())\na = []\ndef bkt():\n    if len(a) == k:\n        print(*a)\n        return\n    for x in range(1, n + 1):\n        if x not in a:\n            a.append(x)\n            bkt()\n            a.pop()\nbkt()', [('3 2','1 2\n1 3\n2 1\n2 3\n3 1\n3 2'),('2 1','1\n2'),('1 1','1')], 'Aplicare')
    add('backtracking', 'Enumeră soluțiile reginelor', 'Citește 1 ≤ n ≤ 6. Afișează toate soluțiile reginelor ca vector de coloane de la 1, câte o valoare pentru fiecare linie, în ordine lexicografică. Fără soluție: NU.', 'Coloanele diferă, iar diferențele absolute de linie și coloană nu sunt egale.', 'n = int(input())\na = []\nfound = False\ndef bkt():\n    global found\n    r = len(a)\n    if r == n:\n        print(*(x + 1 for x in a))\n        found = True\n        return\n    for c in range(n):\n        if all(c != a[i] and abs(c - a[i]) != r - i for i in range(r)):\n            a.append(c)\n            bkt()\n            a.pop()\nbkt()\nif not found:\n    print("NU")', [('4','2 4 1 3\n3 1 4 2'),('1','1'),('2','NU')], 'Aprofundare')
    add('modular', 'Sortări elementare', 'Citește pe prima linie selectie, insertie sau bule, apoi lista de întregi. Implementează metoda cerută fără sorted/sort și afișează lista crescător. Explică timpul O(n²) și diferența dintre metode.', 'Selecția mută minimul; inserția deplasează elementele mai mari; bulele schimbă vecini inversați.', 'method = input()\na = list(map(int, input().split()))\nif method == "selectie":\n    for i in range(len(a)):\n        j = min(range(i, len(a)), key=lambda k: a[k])\n        a[i], a[j] = a[j], a[i]\nelif method == "insertie":\n    for i in range(1, len(a)):\n        x = a[i]\n        j = i - 1\n        while j >= 0 and a[j] > x:\n            a[j + 1] = a[j]\n            j -= 1\n        a[j + 1] = x\nelse:\n    for end in range(len(a) - 1, 0, -1):\n        for j in range(end):\n            if a[j] > a[j + 1]:\n                a[j], a[j + 1] = a[j + 1], a[j]\nprint(*a)', [('selectie\n3 1 2','1 2 3'),('insertie\n2 -1 2','-1 2 2'),('bule\n3 2 1','1 2 3')], 'Aplicare', supplemental=True)
    add('divide', 'Înmulțire Karatsuba', 'Citește două numere naturale de cel mult 30 de cifre. Definește karatsuba(a,b), care folosește trei produse recursive la împărțirea numerelor în două părți. Afișează produsul. Temă suplimentară.', 'Cu a=x*10^m+y și b=u*10^m+v, produsul din mijloc este (x+y)*(u+v)-x*u-y*v.', 'def karatsuba(a, b):\n    if a < 10 or b < 10:\n        return a * b\n    m = max(len(str(a)), len(str(b))) // 2\n    base = 10 ** m\n    x, y = divmod(a, base)\n    u, v = divmod(b, base)\n    p = karatsuba(x, u)\n    q = karatsuba(y, v)\n    r = karatsuba(x + y, u + v) - p - q\n    return p * base * base + r * base + q\na, b = map(int, input().split())\nprint(karatsuba(a, b))', [('123 45','5535'),('0 9876','0'),('99 99','9801')], 'Aprofundare', requiredFunction='karatsuba', supplemental=True)
    add('divide', 'Perechea de puncte apropiate', 'Citește n ≥ 2 și n puncte cu coordonate întregi. Afișează pătratul distanței minime între două puncte distincte prin indice. Aplică Divide et Impera cu banda centrală; discută diferența dintre sortarea repetată și interclasarea listelor după y. Temă suplimentară.', 'Rezolvă jumătățile după x, apoi verifică punctele apropiate de separator; în bandă nu ai nevoie de toate perechile.', 'n = int(input())\na = sorted(tuple(map(int, input().split())) for _ in range(n))\ndef solve(a):\n    if len(a) <= 3:\n        return min(((x[0] - y[0]) ** 2 + (x[1] - y[1]) ** 2 for i, x in enumerate(a) for y in a[i + 1:]), default=float("inf"))\n    m = len(a) // 2\n    mid = a[m][0]\n    d = min(solve(a[:m]), solve(a[m:]))\n    strip = sorted((p for p in a if (p[0] - mid) ** 2 < d), key=lambda p: p[1])\n    for i, p in enumerate(strip):\n        for q in strip[i + 1:i + 8]:\n            d = min(d, (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2)\n    return d\nprint(solve(a))', [('3\n0 0\n3 4\n1 1','2'),('2\n0 0\n3 4','25'),('2\n1 1\n1 1','0')], 'Aprofundare', supplemental=True)
    add('divide', 'Strassen pentru două matrice 2×2', 'Citește două matrice 2×2, fiecare pe două linii. Calculează produsul prin cele șapte înmulțiri Strassen și afișează matricea rezultat. Explică generalizarea recursivă și T(n)=7T(n/2)+O(n²). Temă suplimentară.', 'Produsele celor șapte expresii combină apoi cele patru elemente ale rezultatului.', 'a, b = map(int, input().split())\nc, d = map(int, input().split())\ne, f = map(int, input().split())\ng, h = map(int, input().split())\np1 = (a + d) * (e + h)\np2 = (c + d) * e\np3 = a * (f - h)\np4 = d * (g - e)\np5 = (a + b) * h\np6 = (c - a) * (e + f)\np7 = (b - d) * (g + h)\nprint(p1 + p4 - p5 + p7, p3 + p5)\nprint(p2 + p4, p1 - p2 + p3 + p6)', [('1 2\n3 4\n5 6\n7 8','19 22\n43 50'),('1 0\n0 1\n2 3\n4 5','2 3\n4 5'),('0 0\n0 0\n1 2\n3 4','0 0\n0 0')], 'Aprofundare', supplemental=True)
    add('greedy', 'Intervale închise: săli', 'Citește n și n intervale închise [start,final], start ≤ final. Două intervale care se ating au un punct comun și nu pot fi în aceeași sală. Afișează numărul minim de săli și sala fiecărui interval în ordinea intrării. Orice atribuire optimă este acceptată.', 'Reutilizează o sală numai dacă finalul ei este strict mai mic decât începutul următor.', 'import heapq\nn = int(input())\na = [(*map(int, input().split()), i) for i in range(n)]\na.sort()\nh = []\nresult = [0] * n\nrooms = 0\nfor s, f, i in a:\n    if h and h[0][0] < s:\n        end, room = heapq.heappop(h)\n    else:\n        rooms += 1\n        room = rooms\n    result[i] = room\n    heapq.heappush(h, (f, room))\nprint(rooms)\nprint(*result)', [('2\n0 1\n1 2','2\n1 2'),('2\n0 0\n1 1','1\n1 1'),('0','0\n')], 'Aplicare', validator='rooms-closed')
    add('greedy', 'Intervale închise: selecție', 'Citește n și n intervale închise [start,final], start ≤ final. Afișează numărul maxim de intervale fără niciun punct comun și indicii lor de la 1, în ordinea executării. Atingerea capetelor contează ca intersecție.', 'Ordonează după final și cere start > finalul ultimei alegeri.', 'n = int(input())\na = [(*map(int, input().split()), i + 1) for i in range(n)]\na.sort(key=lambda x: x[1])\nend = None\nb = []\nfor s, f, i in a:\n    if end is None or s > end:\n        b.append(i)\n        end = f\nprint(len(b))\nprint(*b)', [('2\n0 1\n1 2','1\n1'),('2\n0 0\n1 1','2\n1 2'),('0','0\n')], 'Aplicare', validator='activities-closed')
